# We generate parameters for a constrained partition-counting problem.
# The instance enforces nontrivial constraints (min/max block sizes), avoiding the trivial Stirling-only case.
from math import comb

def occupancy_count(r, t, l, u):
    # Count compositions of t into r parts, each in [l,u]
    dp = [0] * (t + 1)
    dp[0] = 1
    for _ in range(r):
        ndp = [0] * (t + 1)
        for s in range(t + 1):
            if dp[s] == 0:
                continue
            for c in range(l, u + 1):
                ns = s + c
                if ns <= t:
                    ndp[ns] += dp[s]
        dp = ndp
    return dp[t]

for _ in range(200):
    alpha = rng.randint(12, 36)
    r = rng.randint(2, min(8, alpha // 2))
    l = rng.randint(1, 3)
    u = rng.randint(l + 1, min(l + 6, alpha))
    t_min = r * l
    t_max = min(alpha, r * u)
    if t_max < t_min:
        continue
    t = rng.randint(t_min, t_max)
    # Choose a composite-ish modulus to avoid prime-field tricks
    modulus = rng.choice([1000, 2000, 5000, 10000, 65536])
    # Difficulty enforcement: avoid trivial Stirling-only case (l==1 and u>=t)
    if l == 1 and u >= t:
        continue
    # Ensure there is more than one occupancy composition to avoid degenerate counts
    occ = occupancy_count(r, t, l, u)
    if occ <= 1:
        continue
    # Also ensure the count isn't tiny; choose t reasonably large relative to alpha
    if t < max(6, r + l):
        continue
    return {'alpha': alpha, 'r': r, 't': t, 'l': l, 'u': u, 'modulus': modulus}
# Fallback (unlikely): pick a safe default
return {'alpha': 20, 'r': 3, 't': 12, 'l': 2, 'u': 5, 'modulus': 10000}

    def verifier(assign):
# Verify domain constraints and compute the count.
# The count equals C(alpha, t) times the number of partitions of a t-element set
# into r unlabeled blocks with sizes in [l, u], i.e., the number of distributions into r labeled boxes
# with each occupancy in [l,u], divided by r!.
from math import comb, factorial

# Extract
try:
    alpha = int(assign['alpha'])
    r = int(assign['r'])
    t = int(assign['t'])
    l = int(assign['l'])
    u = int(assign['u'])
    modulus = int(assign['modulus'])
except Exception:
    # malformed assignment
    return (False, None)  # invalid

# Basic validations
if not (alpha >= 1 and modulus >= 2):
    # invalid domain
    return (False, None)
if not (r >= 2 and 1 <= l <= u):
    return (False, None)
if not (r * l <= t <= min(alpha, r * u)):
    return (False, None)

# Difficulty enforcement: avoid trivial Stirling-only case (l==1 and u>=t)
if l == 1 and u >= t:
    # too easy, violates hardness intent
    return (False, None)

# Count compositions of t into r parts in [l,u] to ensure nontrivial occupancy variety
def occupancy_count(r, t, l, u):
    dp = [0] * (t + 1)
    dp[0] = 1
    for _ in range(r):
        ndp = [0] * (t + 1)
        for s in range(t + 1):
            if dp[s] == 0:
                continue
            for c in range(l, u + 1):
                ns = s + c
                if ns <= t:
                    ndp[ns] += dp[s]
        dp = ndp
    return dp[t]

occ = occupancy_count(r, t, l, u)
if occ <= 1:
    # Degenerate case; not sufficiently challenging
    return (False, None)

# DP for labeled distributions F[i][j] = number of ways to distribute j labeled items
# into i labeled boxes each with size in [l,u]
F = [[0] * (t + 1) for _ in range(r + 1)]
F[0][0] = 1
for i in range(1, r + 1):
    for j in range(0, t + 1):
        total = 0
        lo = l
        hi = min(u, j)
        for c in range(lo, hi + 1):
            total += comb(j, c) * F[i - 1][j - c]
        F[i][j] = total

labeled = F[r][t]
# Convert to unlabeled partitions count by dividing by r!
rf = factorial(r)
if labeled % rf != 0:
    # Sanity check: should be divisible
    return (False, None)
partitions = labeled // rf

# Choose t elements from alpha to be used
total = comb(alpha, t) * partitions
answer = total % modulus
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

